mapper.select:
SELECT ID, TOOL_CODE, USER_ID, BORROW_TIME, RETURN_TIME, STATUS, OPERATOR_TYPE
FROM BORROW_RECORD
WHERE 1=1

    AND (USER_ID LIKE '%' || #{keyword} || '%')


    AND BORROW_TIME >= #{startTime}


    AND BORROW_TIME <= #{endTime}


    AND OPERATOR_TYPE = #{operatorType}

ORDER BY BORROW_TIME DESC
OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

SELECT COUNT(*)
FROM BORROW_RECORD
WHERE 1=1

    AND (USER_ID LIKE '%' || #{keyword} || '%')


    AND BORROW_TIME >= #{startTime}


    AND BORROW_TIME <= #{endTime}


    AND OPERATOR_TYPE = #{operatorType}

SELECT ID, EXCEPTION_TYPE, TOOL_CODE, USER_ID, DESCRIPTION, STATUS, CREATE_TIME, HANDLE_TIME, HANDLER
FROM EXCEPTION_LOG
WHERE 1=1

    AND (USER_ID LIKE '%' || #{keyword} || '%' OR DESCRIPTION LIKE '%' || #{keyword} || '%')


    AND CREATE_TIME >= #{startTime}


    AND CREATE_TIME <= #{endTime}


    AND EXCEPTION_TYPE = #{operatorType}

ORDER BY CREATE_TIME DESC
OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

SELECT COUNT(*)
FROM EXCEPTION_LOG
WHERE 1=1

    AND (USER_ID LIKE '%' || #{keyword} || '%' OR DESCRIPTION LIKE '%' || #{keyword} || '%')


    AND CREATE_TIME >= #{startTime}


    AND CREATE_TIME <= #{endTime}


    AND EXCEPTION_TYPE = #{operatorType}

SELECT COUNT(*)
FROM EXCEPTION_LOG
WHERE STATUS = 'pending'

    AND CREATE_TIME >= #{startTime}


    AND CREATE_TIME <= #{endTime}

SELECT COUNT(*)
FROM BORROW_RECORD
WHERE USER_ID = #{userId}
